// Generated by scripts/build-icon.ps1 from the same paths as the SVG and ICO.
// Edit the canonical geometry in that script, then regenerate all brand assets.
using System.Windows;
using System.Windows.Media;

namespace IconAdapt.App.Controls;

/// <summary>Forma's code-drawn mark, independent of fonts and bitmap scaling.</summary>
public sealed class BrandMark : FrameworkElement
{
    private static readonly DrawingGroup Artwork = CreateArtwork(true);
    private static readonly DrawingGroup CompactArtwork = CreateArtwork(false);

    public BrandMark()
    {
        SnapsToDevicePixels = true;
        UseLayoutRounding = true;
    }

    protected override Size MeasureOverride(Size availableSize) => new(28, 28);

    protected override void OnRender(DrawingContext context)
    {
        base.OnRender(context);
        double side = Math.Min(ActualWidth, ActualHeight);
        if (side <= 0) return;
        context.PushTransform(new TranslateTransform((ActualWidth - side) / 2, (ActualHeight - side) / 2));
        context.PushTransform(new ScaleTransform(side / 256, side / 256));
        context.DrawDrawing(side > 32 ? Artwork : CompactArtwork);
        context.Pop();
        context.Pop();
    }

    private static Color Color(string color) => (Color)ColorConverter.ConvertFromString(color);

    private static Brush Paint(string key)
    {
        Brush brush = key switch
        {
            "Base" => new LinearGradientBrush(new GradientStopCollection { new GradientStop(Color("#475E74"), 0), new GradientStop(Color("#2D4257"), 0.48), new GradientStop(Color("#1B2A3B"), 1) }, new Point(24, 8), new Point(224, 248)) { MappingMode = BrushMappingMode.Absolute },
            "Rear" => new LinearGradientBrush(new GradientStopCollection { new GradientStop(Color("#CAE5EF"), 0), new GradientStop(Color("#A5CBDF"), 0.5), new GradientStop(Color("#729FBC"), 1) }, new Point(128, 48), new Point(208, 164)) { MappingMode = BrushMappingMode.Absolute },
            "Porcelain" => new LinearGradientBrush(new GradientStopCollection { new GradientStop(Color("#FFFFFF"), 0), new GradientStop(Color("#F8F6F0"), 0.48), new GradientStop(Color("#DCE1DD"), 1) }, new Point(80, 88), new Point(144, 208)) { MappingMode = BrushMappingMode.Absolute },
            "Rim" => new LinearGradientBrush(new GradientStopCollection { new GradientStop(Color("#52FFFFFF"), 0), new GradientStop(Color("#05FFFFFF"), 0.45), new GradientStop(Color("#18000000"), 1) }, new Point(0, 8), new Point(0, 248)) { MappingMode = BrushMappingMode.Absolute },
            _ => new SolidColorBrush(Color(key))
        };
        brush.Freeze();
        return brush;
    }

    private static void Add(DrawingGroup drawing, Brush? fill, Brush? stroke, double width, string path, double x, double y)
    {
        var geometry = Geometry.Parse(path);
        if (x != 0 || y != 0) { geometry = geometry.Clone(); geometry.Transform = new TranslateTransform(x, y); }
        drawing.Children.Add(new GeometryDrawing(fill, stroke == null ? null : new Pen(stroke, width) { StartLineCap = PenLineCap.Round, EndLineCap = PenLineCap.Round }, geometry));
    }

    private static DrawingGroup CreateArtwork(bool detailed)
    {
        var drawing = new DrawingGroup();
        Add(drawing, Paint("Base"), null, 0, "M68,8 H188 Q248,8 248,68 V188 Q248,248 188,248 H68 Q8,248 8,188 V68 Q8,8 68,8 Z", 0, 0);
        Add(drawing, Paint("Rear"), null, 0, "M140,48 H180 Q208,48 208,76 V132 Q208,160 180,160 H140 Q112,160 112,132 V76 Q112,48 140,48 Z", 0, 0);
        if (detailed) Add(drawing, Paint("#06091624"), null, 0, "M80,88 H144 Q176,88 176,120 V176 Q176,208 144,208 H80 Q48,208 48,176 V120 Q48,88 80,88 Z", 1, 7);
        if (detailed) Add(drawing, Paint("#08091624"), null, 0, "M80,88 H144 Q176,88 176,120 V176 Q176,208 144,208 H80 Q48,208 48,176 V120 Q48,88 80,88 Z", 1, 5);
        if (detailed) Add(drawing, Paint("#0A091624"), null, 0, "M80,88 H144 Q176,88 176,120 V176 Q176,208 144,208 H80 Q48,208 48,176 V120 Q48,88 80,88 Z", 1, 3);
        if (detailed) Add(drawing, Paint("#10091624"), null, 0, "M80,88 H144 Q176,88 176,120 V176 Q176,208 144,208 H80 Q48,208 48,176 V120 Q48,88 80,88 Z", 0, 1);
        Add(drawing, Paint("Porcelain"), null, 0, "M80,88 H144 Q176,88 176,120 V176 Q176,208 144,208 H80 Q48,208 48,176 V120 Q48,88 80,88 Z", 0, 0);
        Add(drawing, Paint("Base"), null, 0, "M92,120 H132 Q144,120 144,132 V164 Q144,176 132,176 H92 Q80,176 80,164 V132 Q80,120 92,120 Z", 0, 0);
        if (detailed) Add(drawing, null, Paint("Rim"), 1.2, "M68,8 H188 Q248,8 248,68 V188 Q248,248 188,248 H68 Q8,248 8,188 V68 Q8,8 68,8 Z", 0, 0);
        if (detailed) Add(drawing, null, Paint("#D9FFFFFF"), 1.5, "M52,114 Q57,89 80,89 H144 Q165,89 172,108", 0, 0);
        drawing.Freeze();
        return drawing;
    }
}
